node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// List all tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));

// Check columns of each table
tables.forEach(t => {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\nTable:', t.name);
  console.log('Columns:', info.map(c => c.name + ' (' + c.type + ')').join(', '));
  const count = db.prepare('SELECT COUNT(*) as cnt FROM ' + t.name).get();
  console.log('Row count:', count.cnt);
});
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for Logitech mouse or similar products
const mouse = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Mouse%' OR name LIKE '%Logitech%' OR name LIKE '%M310%'\").all();
console.log('Mouse products found:', mouse.length);
mouse.forEach(p => {
  console.log(JSON.stringify({
    product_id: p.product_id,
    name: p.name,
    category: p.category,
    brand: p.brand,
    price: p.price,
    current_price: p.current_price,
    rating: p.rating,
    review_count: p.review_count,
    in_stock: p.in_stock
  }, null, 2));
});
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// All electronics products sorted by rating desc
